window.APP_DATA = {"questions": [{"id": 1, "subject": "History", "question": "Which feature is most strongly associated with mature Harappan cities?", "options": ["Planned drainage systems", "Iron plough agriculture", "Large stone temples", "Coin-based taxation"], "answer": 0, "explanation": "Urban drainage and street planning are hallmark archaeological features.", "te": "పట్టణ మురుగునీటి వ్యవస్థలు హరప్పా నగరాల ముఖ్య లక్షణం."}, {"id": 2, "subject": "History", "question": "Which Harappan site is especially associated with a dockyard interpretation?", "options": ["Kalibangan", "Lothal", "Rakhigarhi", "Banawali"], "answer": 1, "explanation": "Lothal in Gujarat is commonly associated with a dockyard structure.", "te": "గుజరాత్‌లోని లోథల్ డాక్‌యార్డ్‌గా భావించే నిర్మాణంతో ప్రసిద్ధి."}, {"id": 3, "subject": "History", "question": "The Rigveda is primarily a collection of:", "options": ["Legal codes", "Hymns", "Medical treatises", "Drama"], "answer": 1, "explanation": "The Rigveda is the oldest Vedic collection of hymns.", "te": "ఋగ్వేదం ప్రధానంగా స్తోత్రాల సంకలనం."}, {"id": 4, "subject": "History", "question": "The Four Noble Truths are central to:", "options": ["Jainism", "Buddhism", "Ajivikas", "Shaivism"], "answer": 1, "explanation": "The Four Noble Truths form a core part of the Buddha's teaching.", "te": "నాలుగు ఆర్య సత్యాలు బౌద్ధ బోధనలో ప్రధానమైనవి."}, {"id": 5, "subject": "History", "question": "Who is traditionally regarded as the 24th Jain Tirthankara?", "options": ["Parshvanatha", "Rishabhanatha", "Mahavira", "Ajitanatha"], "answer": 2, "explanation": "Mahavira is regarded as the 24th Tirthankara.", "te": "మహావీరుడు 24వ తీర్థంకరుడిగా పరిగణించబడతాడు."}, {"id": 6, "subject": "History", "question": "Ashoka's major rock edicts were generally issued in the context of:", "options": ["Dhamma policy", "Land grants to temples", "Naval expansion", "Abolition of agriculture"], "answer": 0, "explanation": "Ashoka used inscriptions to communicate dhamma and royal policies.", "te": "అశోకుడు ధమ్మం, రాజ విధానాలను తెలియజేయడానికి శాసనాలను ఉపయోగించాడు."}, {"id": 7, "subject": "History", "question": "The Kalinga War is associated with which Mauryan ruler?", "options": ["Bindusara", "Chandragupta Maurya", "Ashoka", "Dasharatha"], "answer": 2, "explanation": "Ashoka's conquest of Kalinga is described in his 13th Major Rock Edict.", "te": "కళింగ యుద్ధం అశోకునితో సంబంధించింది."}, {"id": 8, "subject": "History", "question": "The Allahabad Pillar inscription is associated with:", "options": ["Samudragupta", "Chandragupta I", "Skandagupta", "Harsha"], "answer": 0, "explanation": "The prashasti of Samudragupta was composed by Harisena.", "te": "సముద్రగుప్తుని ప్రశస్తిని హరిసేనుడు రచించాడు."}, {"id": 9, "subject": "History", "question": "The Chola local self-government system is known from inscriptions such as those at:", "options": ["Uttaramerur", "Sanchi", "Taxila", "Sarnath"], "answer": 0, "explanation": "Uttaramerur inscriptions describe village assemblies and committees.", "te": "ఉత్తరమేరు శాసనాలు గ్రామ సభలు, కమిటీల గురించి వివరిస్తాయి."}, {"id": 10, "subject": "History", "question": "The Mansabdari system is associated with the:", "options": ["Delhi Sultanate", "Mughal administration", "Maratha confederacy", "Vijayanagara Empire"], "answer": 1, "explanation": "Mansabs ranked Mughal officials and linked status with military obligations.", "te": "మొఘల్ పాలనలో మన్సబ్ హోదా, సైనిక బాధ్యతలను సూచించింది."}, {"id": 11, "subject": "History", "question": "The Bhakti movement generally emphasised:", "options": ["Devotion", "Only royal sacrifice", "Trade monopolies", "Military conscription"], "answer": 0, "explanation": "Personal devotion was a central theme across many Bhakti traditions.", "te": "భక్తి ఉద్యమంలో వ్యక్తిగత భగవద్భక్తికి ప్రాధాన్యం ఉంది."}, {"id": 12, "subject": "History", "question": "The founder of the Maratha kingdom is widely identified as:", "options": ["Baji Rao I", "Shivaji", "Balaji Vishwanath", "Shahu"], "answer": 1, "explanation": "Shivaji established the foundations of Maratha power.", "te": "శివాజీ మరాఠా శక్తికి పునాది వేశాడు."}, {"id": 13, "subject": "History", "question": "The Battle of Plassey was fought in:", "options": ["1757", "1764", "1773", "1857"], "answer": 0, "explanation": "The Battle of Plassey in 1757 strengthened Company influence in Bengal.", "te": "1757 ప్లాసీ యుద్ధం బెంగాల్‌లో కంపెనీ ప్రభావాన్ని పెంచింది."}, {"id": 14, "subject": "History", "question": "The immediate trigger commonly cited for the 1857 uprising was:", "options": ["Doctrine of Lapse", "Greased cartridge controversy", "Partition of Bengal", "Rowlatt Act"], "answer": 1, "explanation": "The cartridge issue was an immediate trigger amid wider grievances.", "te": "కార్ట్రిడ్జ్ వివాదం విస్తృత అసంతృప్తుల మధ్య తక్షణ కారణమైంది."}, {"id": 15, "subject": "History", "question": "The Government of India Act that transferred rule from the Company to the Crown was passed in:", "options": ["1858", "1861", "1909", "1919"], "answer": 0, "explanation": "The 1858 Act ended East India Company rule.", "te": "1858 చట్టంతో ఈస్ట్ ఇండియా కంపెనీ పాలన ముగిసింది."}, {"id": 16, "subject": "History", "question": "The Indian National Congress was founded in:", "options": ["1885", "1905", "1919", "1935"], "answer": 0, "explanation": "The INC was founded in 1885; A.O. Hume played a key organising role.", "te": "1885లో భారత జాతీయ కాంగ్రెస్ స్థాపించబడింది."}, {"id": 17, "subject": "History", "question": "The Swadeshi movement gained major momentum after:", "options": ["Partition of Bengal (1905)", "Simon Commission", "Cripps Mission", "Cabinet Mission"], "answer": 0, "explanation": "The 1905 partition of Bengal triggered the Swadeshi and boycott movement.", "te": "1905 బెంగాల్ విభజన స్వదేశీ ఉద్యమానికి ఊపునిచ్చింది."}, {"id": 18, "subject": "History", "question": "The Non-Cooperation Movement was launched in:", "options": ["1915", "1920", "1930", "1942"], "answer": 1, "explanation": "Gandhi launched the Non-Cooperation Movement in 1920.", "te": "గాంధీజీ 1920లో సహాయ నిరాకరణ ఉద్యమాన్ని ప్రారంభించారు."}, {"id": 19, "subject": "History", "question": "The Quit India Movement began in:", "options": ["1930", "1935", "1942", "1946"], "answer": 2, "explanation": "The Quit India resolution was adopted in August 1942.", "te": "క్విట్ ఇండియా తీర్మానం ఆగస్టు 1942లో ఆమోదించబడింది."}, {"id": 20, "subject": "History", "question": "The States Reorganisation Act was enacted in:", "options": ["1950", "1956", "1960", "1966"], "answer": 1, "explanation": "The 1956 Act reorganised states largely on linguistic lines.", "te": "1956 రాష్ట్రాల పునర్వ్యవస్థీకరణ చట్టం భాషా ప్రాతిపదికన రాష్ట్రాలను పునర్వ్యవస్థీకరించింది."}, {"id": 21, "subject": "Geography", "question": "The Earth's outermost solid layer is the:", "options": ["Core", "Mantle", "Crust", "Outer core"], "answer": 2, "explanation": "The crust is the outermost solid layer of Earth.", "te": "భూపటలం భూమి వెలుపలి ఘన పొర."}, {"id": 22, "subject": "Geography", "question": "The Himalayas are an example of:", "options": ["Block mountains", "Fold mountains", "Volcanic plateaus", "Residual hills"], "answer": 1, "explanation": "The Himalayas formed through collision of the Indian and Eurasian plates.", "te": "భారత, యూరేషియన్ పలకల ఢీకొనడంతో హిమాలయాలు ఏర్పడ్డాయి."}, {"id": 23, "subject": "Geography", "question": "Most of India's annual rainfall is received from:", "options": ["Northeast monsoon only", "Southwest monsoon", "Western disturbances", "Local convection only"], "answer": 1, "explanation": "The southwest monsoon supplies the major share of India's annual rainfall.", "te": "భారతదేశానికి ప్రధాన వర్షపాతం నైరుతి రుతుపవనాల ద్వారా వస్తుంది."}, {"id": 24, "subject": "Geography", "question": "Which river forms a major delta in Andhra Pradesh?", "options": ["Narmada", "Godavari", "Sabarmati", "Luni"], "answer": 1, "explanation": "The Godavari forms an extensive delta on the Andhra coast.", "te": "గోదావరి ఆంధ్ర తీరంలో విస్తారమైన డెల్టాను ఏర్పరుస్తుంది."}, {"id": 25, "subject": "Geography", "question": "The Krishna river ultimately drains into the:", "options": ["Arabian Sea", "Bay of Bengal", "Gulf of Kutch", "Indian Ocean west coast"], "answer": 1, "explanation": "The Krishna flows eastwards and empties into the Bay of Bengal.", "te": "కృష్ణా నది తూర్పున ప్రవహించి బంగాళాఖాతంలో కలుస్తుంది."}, {"id": 26, "subject": "Geography", "question": "Black soil is particularly suitable for:", "options": ["Cotton", "Tea", "Jute", "Coconut"], "answer": 0, "explanation": "Black soils retain moisture and are widely associated with cotton cultivation.", "te": "నల్ల నేల తేమను నిల్వ ఉంచి పత్తి సాగుకు అనుకూలం."}, {"id": 27, "subject": "Geography", "question": "The Coromandel Coast is located along India's:", "options": ["Northwestern coast", "Southeastern coast", "Western coast", "Northeastern Himalayan foothills"], "answer": 1, "explanation": "The Coromandel Coast is along the southeastern Bay of Bengal coast.", "te": "కోరమాండల్ తీరం ఆగ్నేయ భారత తీరంలో ఉంది."}, {"id": 28, "subject": "Geography", "question": "Tides are primarily caused by gravitational attraction of the:", "options": ["Moon and Sun", "Mars and Jupiter", "Earth's core", "Winds alone"], "answer": 0, "explanation": "Lunar and solar gravitational forces produce tides.", "te": "చంద్రుడు, సూర్యుని గురుత్వాకర్షణ వల్ల ఆటుపోట్లు ఏర్పడతాయి."}, {"id": 29, "subject": "Geography", "question": "A cyclone in the Bay of Bengal generally moves over:", "options": ["Warm ocean waters", "Permanent sea ice", "Dry deserts", "High mountain glaciers"], "answer": 0, "explanation": "Warm ocean water and atmospheric conditions help tropical cyclones intensify.", "te": "వెచ్చని సముద్ర జలాలు తుఫానుల బలాన్ని పెంచుతాయి."}, {"id": 30, "subject": "Geography", "question": "The Eastern Ghats are generally:", "options": ["More continuous than Western Ghats", "Discontinuous and dissected by rivers", "A young fold mountain chain", "Entirely volcanic"], "answer": 1, "explanation": "Major rivers cut across the discontinuous Eastern Ghats.", "te": "తూర్పు కనుమలు విభిన్నంగా ఉండి నదులచే విభజించబడ్డాయి."}, {"id": 31, "subject": "Geography", "question": "The instrument used to measure atmospheric pressure is:", "options": ["Hygrometer", "Barometer", "Anemometer", "Rain gauge"], "answer": 1, "explanation": "A barometer measures atmospheric pressure.", "te": "బారోమీటర్ వాయు పీడనాన్ని కొలుస్తుంది."}, {"id": 32, "subject": "Geography", "question": "The layer of atmosphere where most weather occurs is:", "options": ["Stratosphere", "Troposphere", "Mesosphere", "Thermosphere"], "answer": 1, "explanation": "Most clouds and weather phenomena occur in the troposphere.", "te": "వాతావరణ సంఘటనలు ప్రధానంగా ట్రోపోస్ఫియర్‌లో జరుగుతాయి."}, {"id": 33, "subject": "Geography", "question": "Which is a west-flowing peninsular river?", "options": ["Godavari", "Krishna", "Narmada", "Mahanadi"], "answer": 2, "explanation": "The Narmada flows westward into the Arabian Sea.", "te": "నర్మదా పశ్చిమ దిశగా అరేబియా సముద్రంలో కలుస్తుంది."}, {"id": 34, "subject": "Geography", "question": "Mangrove vegetation is commonly found in:", "options": ["Tidal deltas and estuaries", "Cold deserts", "Alpine meadows", "High plateaus"], "answer": 0, "explanation": "Mangroves are adapted to saline, tidal coastal environments.", "te": "మడ అడవులు ఉప్పునీటి, ఆటుపోట్ల తీర ప్రాంతాలకు అనుకూలం."}, {"id": 35, "subject": "Geography", "question": "Which is a major natural hazard for the Andhra coast?", "options": ["Tropical cyclones", "Avalanches", "Glacial lake outburst floods", "Volcanic ash"], "answer": 0, "explanation": "The Bay of Bengal exposes the Andhra coast to tropical cyclones and storm surges.", "te": "బంగాళాఖాత తుఫానులు, తుఫాను అలలు ఆంధ్ర తీరానికి ప్రధాన ప్రమాదాలు."}, {"id": 36, "subject": "Geography", "question": "A population pyramid is used to study:", "options": ["Age-sex composition", "Soil texture", "Ocean salinity", "Rock hardness"], "answer": 0, "explanation": "Population pyramids show age and sex structure.", "te": "జనాభా పిరమిడ్ వయస్సు–లింగ నిర్మాణాన్ని చూపుతుంది."}, {"id": 37, "subject": "Geography", "question": "Urbanisation refers to:", "options": ["Decline in towns", "Increasing share of people living in urban areas", "Only international migration", "Growth of forests"], "answer": 1, "explanation": "Urbanisation is the rising proportion of population living in urban settlements.", "te": "పట్టణ ప్రాంతాల్లో నివసించే జనాభా వాటా పెరగడమే పట్టణీకరణ."}, {"id": 38, "subject": "Geography", "question": "Which activity belongs to the primary sector?", "options": ["Banking", "Agriculture", "Software services", "Retail trade"], "answer": 1, "explanation": "Agriculture directly uses natural resources and is part of the primary sector.", "te": "వ్యవసాయం ప్రాథమిక రంగానికి చెందుతుంది."}, {"id": 39, "subject": "Geography", "question": "A port is part of which infrastructure category?", "options": ["Transport", "Education", "Public health", "Judiciary"], "answer": 0, "explanation": "Ports are nodes in maritime transport and trade networks.", "te": "ఓడరేవులు సముద్ర రవాణా, వాణిజ్య మౌలిక సదుపాయాలు."}, {"id": 40, "subject": "Geography", "question": "The scale on a map represents:", "options": ["Relationship between map distance and ground distance", "Only elevation", "Population density", "Annual rainfall"], "answer": 0, "explanation": "Map scale expresses the ratio between map and real-world distances.", "te": "మ్యాప్‌లోని దూరం, భూమిపై నిజమైన దూరం మధ్య నిష్పత్తి మ్యాప్ స్కేలు."}, {"id": 41, "subject": "Society", "question": "Kinship refers primarily to:", "options": ["Relations based on blood, marriage or adoption", "Only employment contracts", "Only political parties", "Market exchange"], "answer": 0, "explanation": "Kinship systems organise relationships through descent, marriage and adoption.", "te": "రక్త సంబంధం, వివాహం, దత్తత ఆధారంగా ఏర్పడే బంధాలు బంధుత్వం."}, {"id": 42, "subject": "Society", "question": "A joint family traditionally includes:", "options": ["Only one individual", "Multiple related generations or nuclear units", "Only unrelated workers", "Only elected representatives"], "answer": 1, "explanation": "Joint-family arrangements commonly include related members across generations.", "te": "ఉమ్మడి కుటుంబంలో అనేక తరాల బంధువులు కలిసి ఉండవచ్చు."}, {"id": 43, "subject": "Society", "question": "Social mobility means:", "options": ["Movement between social positions", "Movement of tectonic plates", "Seasonal rainfall", "Change in currency"], "answer": 0, "explanation": "Social mobility is movement within or between social strata.", "te": "సామాజిక స్థితుల మధ్య మార్పును సామాజిక చలనం అంటారు."}, {"id": 44, "subject": "Society", "question": "Communalism in the Indian social context is associated with:", "options": ["Political or social antagonism organised around religious communities", "Only language learning", "Forest conservation", "Urban planning"], "answer": 0, "explanation": "Communalism involves treating religious communities as antagonistic political interests.", "te": "మత సమూహాల మధ్య విరోధాన్ని రాజకీయంగా వినియోగించడం మతతత్వం."}, {"id": 45, "subject": "Society", "question": "Child labour is addressed in India through:", "options": ["Constitutional provisions and labour laws", "Only private charity", "Only school sports rules", "No legal framework"], "answer": 0, "explanation": "India has constitutional protections and legislation regulating child labour.", "te": "బాల కార్మికత్వాన్ని నియంత్రించేందుకు రాజ్యాంగ రక్షణలు, చట్టాలు ఉన్నాయి."}, {"id": 46, "subject": "Society", "question": "The term patriarchy describes:", "options": ["A social system where men hold disproportionate power", "A type of rainfall", "A tax system", "A voting method"], "answer": 0, "explanation": "Patriarchy refers to institutionalised male dominance in social structures.", "te": "సామాజిక వ్యవస్థల్లో పురుషాధిక్యతను పితృస్వామ్యం అంటారు."}, {"id": 47, "subject": "Society", "question": "The Constitution abolishes untouchability under:", "options": ["Article 14", "Article 17", "Article 21A", "Article 32"], "answer": 1, "explanation": "Article 17 abolishes untouchability and forbids its practice.", "te": "ఆర్టికల్ 17 అంటరానితనాన్ని రద్దు చేస్తుంది."}, {"id": 48, "subject": "Society", "question": "The National Commission for Scheduled Castes is provided under:", "options": ["Article 338", "Article 280", "Article 324", "Article 148"], "answer": 0, "explanation": "Article 338 provides for the National Commission for Scheduled Castes.", "te": "ఆర్టికల్ 338 జాతీయ షెడ్యూల్డ్ కులాల కమిషన్‌కు సంబంధించినది."}, {"id": 49, "subject": "Society", "question": "The Directive Principles are contained in:", "options": ["Part III", "Part IV", "Part IVA", "Part V"], "answer": 1, "explanation": "Directive Principles of State Policy are in Part IV.", "te": "ఆదేశిక సూత్రాలు రాజ్యాంగంలోని భాగం IVలో ఉన్నాయి."}, {"id": 50, "subject": "Society", "question": "The Right to Education for children aged 6–14 is under:", "options": ["Article 19", "Article 21A", "Article 25", "Article 40"], "answer": 1, "explanation": "Article 21A provides free and compulsory education for ages 6–14.", "te": "6–14 ఏళ్ల పిల్లలకు విద్య హక్కు ఆర్టికల్ 21Aలో ఉంది."}, {"id": 51, "subject": "Society", "question": "A tribe is often characterised by:", "options": ["Shared cultural identity and community ties", "A single occupation in every case", "One universal language", "Absence of social institutions"], "answer": 0, "explanation": "Tribal communities are diverse; shared identity, kinship and cultural practices may be important features.", "te": "గిరిజన సమాజాలు విభిన్నమైనవి; సామూహిక గుర్తింపు, బంధుత్వం, సంస్కృతి ముఖ్య లక్షణాలు కావచ్చు."}, {"id": 52, "subject": "Society", "question": "The Protection of Women from Domestic Violence Act was enacted in:", "options": ["2005", "2010", "1993", "1986"], "answer": 0, "explanation": "The Protection of Women from Domestic Violence Act is from 2005.", "te": "గృహహింస నుంచి మహిళల రక్షణ చట్టం 2005లో వచ్చింది."}, {"id": 53, "subject": "Society", "question": "The term secularism in India broadly implies:", "options": ["State principled treatment of religions without establishing an official state religion", "A ban on all religious practice", "Rule by religious clergy", "Only one permitted religion"], "answer": 0, "explanation": "Indian secularism is based on constitutional equality and principled state engagement with religion.", "te": "భారత లౌకికవాదం రాజ్యాంగ సమానత్వం, మతాల పట్ల సమాన దృక్పథంపై ఆధారితం."}, {"id": 54, "subject": "Society", "question": "The main purpose of affirmative action is to:", "options": ["Address historical disadvantage and improve representation", "Increase inflation", "Reduce literacy", "Replace elections"], "answer": 0, "explanation": "Affirmative action seeks to remedy structural exclusion and unequal opportunity.", "te": "చారిత్రక వెనుకబాటుతనాన్ని తగ్గించి అవకాశాలు, ప్రాతినిధ్యం పెంచడం లక్ష్యం."}, {"id": 55, "subject": "Society", "question": "Regionalisation refers to:", "options": ["Formation or strengthening of identities and demands around a region", "Only global trade", "A type of soil", "A banking instrument"], "answer": 0, "explanation": "Regionalisation concerns regional identities, interests and political demands.", "te": "ప్రాంతీయ గుర్తింపులు, ప్రయోజనాలు, డిమాండ్ల బలపడటాన్ని ప్రాంతీయత అంటారు."}, {"id": 56, "subject": "Society", "question": "The main purpose of a statutory commission is to:", "options": ["Perform functions created by legislation", "Replace the Supreme Court", "Conduct all elections", "Prepare school textbooks only"], "answer": 0, "explanation": "A statutory body derives its mandate from an Act of the legislature.", "te": "చట్టం ద్వారా ఏర్పడి నిర్దిష్ట అధికారాలు, బాధ్యతలు నిర్వర్తించే సంస్థ చట్టబద్ధ కమిషన్."}, {"id": 57, "subject": "Society", "question": "The term pluralism refers to:", "options": ["Coexistence of diverse groups and viewpoints", "One uniform culture imposed on all", "Only economic growth", "A form of taxation"], "answer": 0, "explanation": "Pluralism recognises diversity and coexistence within society.", "te": "విభిన్న సమూహాలు, అభిప్రాయాల సహజీవనాన్ని బహుళత్వం అంటారు."}, {"id": 58, "subject": "Society", "question": "A major aim of child protection policy is to:", "options": ["Safeguard children from abuse, exploitation and neglect", "Increase child employment", "Exclude children from education", "Restrict immunisation"], "answer": 0, "explanation": "Child protection focuses on safety, rights, development and participation.", "te": "బాలల రక్షణ లక్ష్యం దుర్వినియోగం, దోపిడీ, నిర్లక్ష్యం నుంచి రక్షణ."}, {"id": 59, "subject": "Society", "question": "Caste and class differ because class is commonly more closely linked to:", "options": ["Economic position and life chances", "Birth ritual alone", "A fixed religious text", "Only language"], "answer": 0, "explanation": "Class is commonly analysed through economic position, resources and opportunities.", "te": "వర్గం సాధారణంగా ఆర్థిక స్థితి, వనరులు, అవకాశాలతో ఎక్కువగా సంబంధించింది."}, {"id": 60, "subject": "Society", "question": "A public welfare programme should be evaluated using:", "options": ["Coverage, outcomes, inclusion and implementation quality", "Only its slogan", "Only launch date", "Only the logo"], "answer": 0, "explanation": "Evaluation should consider reach, results, equity and delivery.", "te": "పథకాన్ని చేరిక, ఫలితాలు, సమానత్వం, అమలు నాణ్యత ఆధారంగా అంచనా వేయాలి."}, {"id": 61, "subject": "Current Affairs", "question": "Which source is most appropriate for verifying a Union government press release?", "options": ["PIB", "Anonymous social-media forward", "Unattributed blog", "Old coaching note"], "answer": 0, "explanation": "The Press Information Bureau is an official source for Union government releases.", "te": "కేంద్ర ప్రభుత్వ ప్రకటనలను ధృవీకరించడానికి PIB అధికారిక మూలం."}, {"id": 62, "subject": "Current Affairs", "question": "For current Andhra Pradesh government schemes, the best primary source is:", "options": ["Relevant AP government department/official portal", "Unverified messaging group", "Old exam guide only", "Anonymous video"], "answer": 0, "explanation": "Departmental and official state portals are primary sources for scheme details.", "te": "AP పథకాల వివరాలకు సంబంధిత ప్రభుత్వ శాఖ/అధికారిక పోర్టల్ ప్రాథమిక మూలం."}, {"id": 63, "subject": "Current Affairs", "question": "A good current-affairs note should record:", "options": ["Event, date, institution, significance and verified facts", "Only a headline", "Only an opinion", "Only a photograph"], "answer": 0, "explanation": "Structured notes improve recall and reduce factual confusion.", "te": "సంఘటన, తేదీ, సంస్థ, ప్రాముఖ్యత, ధృవీకరించిన వాస్తవాలు నమోదు చేయాలి."}, {"id": 64, "subject": "Current Affairs", "question": "An international climate conference under the UN climate process is commonly called:", "options": ["COP", "CPT", "CAG", "CVC"], "answer": 0, "explanation": "COP refers to Conference of the Parties under a convention such as the UNFCCC.", "te": "COP అనేది UNFCCC వంటి ఒప్పందంలోని పార్టీల సమావేశం."}, {"id": 65, "subject": "Current Affairs", "question": "The Union Budget is constitutionally presented under the annual financial statement provision:", "options": ["Article 112", "Article 110", "Article 123", "Article 356"], "answer": 0, "explanation": "Article 112 provides for the Annual Financial Statement.", "te": "ఆర్టికల్ 112 వార్షిక ఆర్థిక ప్రకటనకు సంబంధించినది."}, {"id": 66, "subject": "Current Affairs", "question": "The Economic Survey is generally presented:", "options": ["Before the Union Budget", "After every state election", "Only once in five years", "By the Supreme Court"], "answer": 0, "explanation": "The Economic Survey is normally tabled ahead of the Union Budget.", "te": "ఆర్థిక సర్వే సాధారణంగా కేంద్ర బడ్జెట్‌కు ముందు ప్రవేశపెడతారు."}, {"id": 67, "subject": "Current Affairs", "question": "Which organisation releases the World Economic Outlook?", "options": ["IMF", "WHO", "UNICEF", "ILO"], "answer": 0, "explanation": "The International Monetary Fund publishes the World Economic Outlook.", "te": "ప్రపంచ ఆర్థిక దృక్పథ నివేదికను IMF విడుదల చేస్తుంది."}, {"id": 68, "subject": "Current Affairs", "question": "The Sustainable Development Goals were adopted by the UN in:", "options": ["2015", "2000", "2020", "1992"], "answer": 0, "explanation": "The 2030 Agenda and SDGs were adopted in 2015.", "te": "2030 అజెండా, SDGs 2015లో ఆమోదించబడ్డాయి."}, {"id": 69, "subject": "Current Affairs", "question": "ISRO is India's national space agency. Its headquarters are in:", "options": ["Bengaluru", "Hyderabad", "New Delhi", "Sriharikota"], "answer": 0, "explanation": "ISRO headquarters are in Bengaluru.", "te": "ఇస్రో ప్రధాన కార్యాలయం బెంగళూరులో ఉంది."}, {"id": 70, "subject": "Current Affairs", "question": "The Reserve Bank of India's primary role includes:", "options": ["Monetary policy and currency management", "Conducting parliamentary elections", "Managing school curricula", "Issuing passports"], "answer": 0, "explanation": "RBI is India's central bank and performs monetary and regulatory functions.", "te": "RBI భారత కేంద్ర బ్యాంకు; ద్రవ్య విధానం, నియంత్రణ బాధ్యతలు నిర్వహిస్తుంది."}, {"id": 71, "subject": "Current Affairs", "question": "A government report's 'base year' is important because it:", "options": ["Provides the reference year for comparing an index or series", "Shows the report's printing date", "Names the author", "Indicates the number of pages"], "answer": 0, "explanation": "A base year is the reference point for index calculations and comparisons.", "te": "సూచీ లెక్కలు, పోలికలకు ఆధార సంవత్సరాన్ని ఉపయోగిస్తారు."}, {"id": 72, "subject": "Current Affairs", "question": "A Supreme Court judgment should be studied for:", "options": ["Issue, constitutional/legal principle and outcome", "Only the judge's photograph", "Only social-media reaction", "Only the case number"], "answer": 0, "explanation": "Exam notes should capture the legal issue, principle and ruling.", "te": "తీర్పులో న్యాయ సమస్య, సూత్రం, తుది నిర్ణయం గుర్తుంచుకోవాలి."}, {"id": 73, "subject": "Current Affairs", "question": "Which is a primary source for India's official statistical releases?", "options": ["Ministry/official statistical agency publication", "Anonymous infographic", "Old newspaper clipping", "Unverified spreadsheet"], "answer": 0, "explanation": "Official statistical releases should be taken from the responsible government agency.", "te": "అధికారిక గణాంకాలను సంబంధిత ప్రభుత్వ గణాంక సంస్థ నుంచి తీసుకోవాలి."}, {"id": 74, "subject": "Current Affairs", "question": "When a current-affairs figure is revised, a learner should:", "options": ["Use the latest official release and note the reference period", "Keep both figures without dates", "Choose the larger number", "Ignore the source"], "answer": 0, "explanation": "Always retain date, reference period and issuing source when figures change.", "te": "గణాంకం మారితే తాజా అధికారిక ప్రకటన, సూచన కాలం నమోదు చేయాలి."}, {"id": 75, "subject": "Current Affairs", "question": "Which item is most clearly a state-level current-affairs topic for APPSC?", "options": ["A new Andhra Pradesh state policy announcement", "A centuries-old Roman law", "A generic algebra identity", "A fictional news story"], "answer": 0, "explanation": "State policies and developments in Andhra Pradesh are directly relevant.", "te": "ఆంధ్రప్రదేశ్ ప్రభుత్వ కొత్త విధానం రాష్ట్ర స్థాయి కరెంట్ అఫైర్స్."}, {"id": 76, "subject": "Current Affairs", "question": "BRICS is best described as:", "options": ["A grouping of major emerging economies", "A UN specialised agency", "A military alliance founded by NATO", "A global court"], "answer": 0, "explanation": "BRICS is a forum/grouping of emerging economies.", "te": "BRICS అభివృద్ధి చెందుతున్న ప్రధాన ఆర్థిక వ్యవస్థల వేదిక."}, {"id": 77, "subject": "Current Affairs", "question": "A reliable way to study awards is to record:", "options": ["Award, recipient, field, awarding body and year", "Only recipient's name", "Only a rumour", "Only the ceremony venue"], "answer": 0, "explanation": "These fields make award-related facts precise and revision-friendly.", "te": "అవార్డు, గ్రహీత, రంగం, ప్రదాత సంస్థ, సంవత్సరం నమోదు చేయాలి."}, {"id": 78, "subject": "Current Affairs", "question": "For a policy announcement, the most useful exam question often asks:", "options": ["Objective, target group, implementing body and key feature", "Only the colour of the logo", "Only the speech length", "Only the venue"], "answer": 0, "explanation": "Policy questions commonly test purpose, beneficiaries and implementation.", "te": "విధానం లక్ష్యం, లబ్ధిదారులు, అమలు సంస్థ, ముఖ్య లక్షణం తెలుసుకోవాలి."}, {"id": 79, "subject": "Current Affairs", "question": "A news item should be excluded from notes when it is:", "options": ["Unverified and unsupported by credible sources", "Officially notified", "Confirmed by multiple primary sources", "Relevant to the syllabus"], "answer": 0, "explanation": "Unverified claims should not be memorised as facts.", "te": "ధృవీకరించని సమాచారాన్ని వాస్తవంగా చదవకూడదు."}, {"id": 80, "subject": "Current Affairs", "question": "The best weekly revision method is to:", "options": ["Convert daily notes into short topic-wise questions", "Read every article again without selection", "Delete dated notes", "Memorise headlines only"], "answer": 0, "explanation": "Active recall through questions strengthens retention.", "te": "రోజువారీ నోట్స్‌ను ప్రశ్నలుగా మార్చి యాక్టివ్ రీకాల్ చేయాలి."}, {"id": 81, "subject": "Mental Ability", "question": "What is the next number: 2, 4, 8, 16, __?", "options": ["18", "24", "32", "36"], "answer": 2, "explanation": "Each term is multiplied by 2; next is 32.", "te": "ప్రతి సంఖ్యను 2తో గుణిస్తున్నారు; తదుపరి 32."}, {"id": 82, "subject": "Mental Ability", "question": "Find the odd one out: 3, 5, 7, 9, 11", "options": ["3", "5", "9", "11"], "answer": 2, "explanation": "9 is composite; the others are prime.", "te": "9 సంయుక్త సంఖ్య; మిగతావి ప్రధాన సంఖ్యలు."}, {"id": 83, "subject": "Mental Ability", "question": "If CAT is coded as DBU, DOG is coded as:", "options": ["EPH", "CNG", "FQI", "EOG"], "answer": 0, "explanation": "Each letter is shifted one place forward.", "te": "ప్రతి అక్షరాన్ని ఒక స్థానం ముందుకు మార్చారు."}, {"id": 84, "subject": "Mental Ability", "question": "A is the brother of B. B is the mother of C. A is C's:", "options": ["Father", "Maternal uncle", "Brother", "Grandfather"], "answer": 1, "explanation": "A is the brother of C's mother, so he is the maternal uncle.", "te": "C తల్లి సోదరుడు కాబట్టి మేనమామ."}, {"id": 85, "subject": "Mental Ability", "question": "A person walks 3 km north and then 4 km east. How far is the person from the start?", "options": ["5 km", "6 km", "7 km", "12 km"], "answer": 0, "explanation": "By Pythagoras, distance = √(3²+4²) = 5 km.", "te": "పైథాగరస్ సూత్రం ప్రకారం √(9+16)=5 కి.మీ."}, {"id": 86, "subject": "Mental Ability", "question": "The average of 6, 8 and 10 is:", "options": ["7", "8", "9", "10"], "answer": 1, "explanation": "Average = (6+8+10)/3 = 8.", "te": "సగటు = 24/3 = 8."}, {"id": 87, "subject": "Mental Ability", "question": "25% of 240 equals:", "options": ["40", "50", "60", "80"], "answer": 2, "explanation": "0.25 × 240 = 60.", "te": "240లో 25 శాతం = 60."}, {"id": 88, "subject": "Mental Ability", "question": "The ratio 12:18 in simplest form is:", "options": ["2:3", "3:2", "4:5", "6:9"], "answer": 0, "explanation": "Divide both terms by 6 to get 2:3.", "te": "రెండు భాగాలను 6తో భాగిస్తే 2:3."}, {"id": 89, "subject": "Mental Ability", "question": "Simple interest on ₹2,000 at 5% per annum for 2 years is:", "options": ["₹100", "₹150", "₹200", "₹250"], "answer": 2, "explanation": "SI = PRT/100 = 2000×5×2/100 = ₹200.", "te": "సరళ వడ్డీ = 2000×5×2/100 = ₹200."}, {"id": 90, "subject": "Mental Ability", "question": "A can finish work in 10 days and B in 15 days. Together they finish in:", "options": ["5 days", "6 days", "8 days", "12 days"], "answer": 1, "explanation": "Combined rate = 1/10 + 1/15 = 1/6 job per day.", "te": "కలిపిన పని రేటు 1/10+1/15=1/6; 6 రోజులు."}, {"id": 91, "subject": "Mental Ability", "question": "A vehicle travels 150 km in 3 hours. Its average speed is:", "options": ["30 km/h", "40 km/h", "50 km/h", "60 km/h"], "answer": 2, "explanation": "Speed = distance/time = 150/3 = 50 km/h.", "te": "వేగం = 150/3 = 50 కి.మీ/గం."}, {"id": 92, "subject": "Mental Ability", "question": "Find the next letter: A, C, E, G, __", "options": ["H", "I", "J", "K"], "answer": 1, "explanation": "Letters advance by two positions; next is I.", "te": "ప్రతి సారి రెండు అక్షరాలు దాటుతున్నాయి; తదుపరి I."}, {"id": 93, "subject": "Mental Ability", "question": "If all roses are flowers and some flowers fade quickly, which conclusion definitely follows?", "options": ["All roses fade quickly", "Some roses fade quickly", "All roses are flowers", "No flowers are roses"], "answer": 2, "explanation": "Only the first premise is universally certain for roses.", "te": "అన్ని గులాబీలు పూలే అనే నిర్ధారణ మాత్రమే ఖచ్చితం."}, {"id": 94, "subject": "Mental Ability", "question": "A statement is followed by an assumption. An assumption is:", "options": ["An unstated idea taken for granted", "Always a proven fact", "A conclusion that must be false", "A numerical average"], "answer": 0, "explanation": "An assumption is an implicit premise underlying a statement.", "te": "వాక్యానికి ఆధారంగా అంతర్లీనంగా తీసుకున్న భావన ఊహ."}, {"id": 95, "subject": "Mental Ability", "question": "If 5 workers complete a task in 12 days, at the same rate 10 workers take:", "options": ["3 days", "6 days", "10 days", "24 days"], "answer": 1, "explanation": "Work is constant; doubling workers halves time to 6 days.", "te": "పనివారు రెట్టింపు అయితే సమయం సగం: 6 రోజులు."}, {"id": 96, "subject": "Mental Ability", "question": "A shop gives 10% discount on ₹800. Sale price is:", "options": ["₹700", "₹720", "₹740", "₹780"], "answer": 1, "explanation": "Discount = ₹80; sale price = ₹720.", "te": "తగ్గింపు ₹80; అమ్మకపు ధర ₹720."}, {"id": 97, "subject": "Mental Ability", "question": "Compound interest on ₹1,000 at 10% annually for 2 years is:", "options": ["₹200", "₹210", "₹220", "₹121"], "answer": 1, "explanation": "Amount = 1000×1.1² = 1210; CI = ₹210.", "te": "మొత్తం 1210; చక్రవడ్డీ ₹210."}, {"id": 98, "subject": "Mental Ability", "question": "Which graph is generally best for showing change over time?", "options": ["Line graph", "Pie chart only", "Pictogram only", "Flow chart"], "answer": 0, "explanation": "Line graphs are useful for trends over continuous time.", "te": "కాలానుగుణ మార్పులను రేఖాచిత్రం స్పష్టంగా చూపుతుంది."}, {"id": 99, "subject": "Mental Ability", "question": "If 40% of a number is 80, the number is:", "options": ["160", "180", "200", "240"], "answer": 2, "explanation": "Number = 80/0.4 = 200.", "te": "సంఖ్య = 80/0.4 = 200."}, {"id": 100, "subject": "Mental Ability", "question": "A clock shows 3:00. The angle between the hour and minute hands is:", "options": ["45°", "60°", "90°", "120°"], "answer": 2, "explanation": "At 3:00 the hands are perpendicular: 90 degrees.", "te": "3 గంటలకు ముళ్ల మధ్య కోణం 90°."}, {"id": 101, "subject": "History", "question": "Which Harappan site is known for its large water reservoirs?", "options": ["Dholavira", "Lothal", "Surkotada", "Chanhudaro"], "answer": 0, "explanation": "Dholavira is noted for sophisticated water conservation and reservoirs.", "te": "ధోలవీరా నీటి సంరక్షణ, జలాశయాల నిర్మాణానికి ప్రసిద్ధి."}, {"id": 102, "subject": "History", "question": "The Great Bath was discovered at:", "options": ["Harappa", "Mohenjo-daro", "Lothal", "Ropar"], "answer": 1, "explanation": "The Great Bath is a well-known structure at Mohenjo-daro.", "te": "గ్రేట్ బాత్ మొహెంజోదారోలో కనుగొనబడింది."}, {"id": 103, "subject": "History", "question": "The Upanishads are mainly concerned with:", "options": ["Philosophical ideas", "Military campaigns", "Trade tariffs", "Temple taxation"], "answer": 0, "explanation": "The Upanishads explore philosophical and spiritual questions.", "te": "ఉపనిషత్తులు తాత్విక, ఆధ్యాత్మిక భావనలను చర్చిస్తాయి."}, {"id": 104, "subject": "History", "question": "The capital of the Mauryan Empire under Chandragupta Maurya was:", "options": ["Pataliputra", "Ujjain", "Taxila", "Kanchi"], "answer": 0, "explanation": "Pataliputra was the Mauryan imperial capital.", "te": "చంద్రగుప్త మౌర్యుని రాజధాని పాటలీపుత్రం."}, {"id": 105, "subject": "History", "question": "Megasthenes visited the court of:", "options": ["Ashoka", "Chandragupta Maurya", "Samudragupta", "Harsha"], "answer": 1, "explanation": "Megasthenes was an ambassador at Chandragupta Maurya's court.", "te": "మెగస్తనీస్ చంద్రగుప్త మౌర్యుని ఆస్థానానికి వచ్చాడు."}, {"id": 106, "subject": "History", "question": "The Gupta ruler associated with the title Vikramaditya is commonly:", "options": ["Chandragupta II", "Kumaragupta I", "Skandagupta", "Ghatotkacha"], "answer": 0, "explanation": "Chandragupta II is commonly associated with the title Vikramaditya.", "te": "విక్రమాదిత్య బిరుదుతో చంద్రగుప్తుడు II ప్రసిద్ధి."}, {"id": 107, "subject": "History", "question": "The Brihadeshwara Temple at Thanjavur was built by:", "options": ["Rajaraja Chola I", "Rajendra Chola I", "Kulottunga I", "Parantaka I"], "answer": 0, "explanation": "Rajaraja Chola I commissioned the Brihadeshwara Temple.", "te": "బృహదీశ్వర ఆలయాన్ని రాజరాజ చోళుడు నిర్మింపజేశాడు."}, {"id": 108, "subject": "History", "question": "The first Battle of Panipat (1526) was fought between Babur and:", "options": ["Ibrahim Lodi", "Rana Sanga", "Sher Shah Suri", "Hemu"], "answer": 0, "explanation": "Babur defeated Ibrahim Lodi in 1526.", "te": "1526లో బాబర్ ఇబ్రహీం లోదీని ఓడించాడు."}, {"id": 109, "subject": "History", "question": "The Din-i Ilahi was introduced by:", "options": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "answer": 0, "explanation": "Akbar introduced Din-i Ilahi as a small ethical-religious order.", "te": "దీన్-ఇ-ఇలాహీని అక్బర్ ప్రవేశపెట్టాడు."}, {"id": 110, "subject": "History", "question": "The Subsidiary Alliance system is associated with:", "options": ["Lord Wellesley", "Lord Dalhousie", "Lord Ripon", "Lord Curzon"], "answer": 0, "explanation": "Lord Wellesley expanded Company influence through Subsidiary Alliances.", "te": "సహాయక సంధి విధానాన్ని వెల్లెస్లీ విస్తరించాడు."}, {"id": 111, "subject": "Geography", "question": "The boundary between the troposphere and stratosphere is called:", "options": ["Tropopause", "Stratopause", "Mesopause", "Thermopause"], "answer": 0, "explanation": "The tropopause separates the troposphere and stratosphere.", "te": "ట్రోపోపాజ్ ట్రోపోస్ఫియర్, స్ట్రాటోస్ఫియర్‌ను వేరు చేస్తుంది."}, {"id": 112, "subject": "Geography", "question": "The Coriolis force is caused by Earth's:", "options": ["Rotation", "Revolution", "Gravity alone", "Magnetic field"], "answer": 0, "explanation": "Earth's rotation deflects moving air and water, producing the Coriolis effect.", "te": "భూమి భ్రమణం వల్ల కోరియోలిస్ ప్రభావం ఏర్పడుతుంది."}, {"id": 113, "subject": "Geography", "question": "The rain-shadow region lies generally on the:", "options": ["Leeward side of a mountain", "Windward side only", "Mountain summit", "Ocean floor"], "answer": 0, "explanation": "Descending air on the leeward side is generally drier.", "te": "పర్వతం గాలి ఎదురుకాని వైపున వర్షఛాయ ప్రాంతం ఏర్పడుతుంది."}, {"id": 114, "subject": "Geography", "question": "Laterite soils commonly develop under conditions of:", "options": ["High temperature and heavy rainfall", "Permanent frost", "Very low rainfall", "Glacial deposition"], "answer": 0, "explanation": "Intense leaching under hot, wet conditions forms lateritic soils.", "te": "వేడి, అధిక వర్షపాతం వల్ల లేటరైట్ నేలలు ఏర్పడతాయి."}, {"id": 115, "subject": "Geography", "question": "The largest share of India's freshwater use is generally for:", "options": ["Agriculture", "Aviation", "Household use only", "Mining only"], "answer": 0, "explanation": "Agriculture accounts for the largest share of freshwater withdrawals in India.", "te": "భారతదేశంలో తీపినీటి వినియోగంలో వ్యవసాయానికి అత్యధిక వాటా ఉంటుంది."}, {"id": 116, "subject": "Geography", "question": "A delta is formed mainly by:", "options": ["Deposition of river sediments", "Glacial erosion", "Wind deflation", "Volcanic eruption"], "answer": 0, "explanation": "River-borne sediments accumulate near the river mouth to form a delta.", "te": "నది తెచ్చిన అవక్షేపాలు ముఖద్వారం వద్ద పేరుకుపోయి డెల్టా ఏర్పడుతుంది."}, {"id": 117, "subject": "Geography", "question": "El Niño is associated with abnormal warming in the:", "options": ["Central/eastern equatorial Pacific", "North Atlantic", "Arabian Sea", "Southern Indian Ocean"], "answer": 0, "explanation": "El Niño involves warming of central and eastern equatorial Pacific waters.", "te": "ఎల్ నినో మధ్య, తూర్పు భూమధ్యరేఖ పసిఫిక్ జలాల వేడెక్కుదల."}, {"id": 118, "subject": "Geography", "question": "The main source of energy driving the water cycle is:", "options": ["Solar energy", "Earthquake energy", "Tidal energy alone", "Geothermal energy alone"], "answer": 0, "explanation": "Solar energy drives evaporation and the hydrological cycle.", "te": "సౌరశక్తి ఆవిరీభవనాన్ని, జలచక్రాన్ని నడిపిస్తుంది."}, {"id": 119, "subject": "Geography", "question": "Contour lines on a topographic map join points of equal:", "options": ["Elevation", "Rainfall", "Temperature", "Population"], "answer": 0, "explanation": "Contours connect locations with the same elevation.", "te": "సమాన ఎత్తు ఉన్న ప్రదేశాలను కాంటూర్ రేఖలు కలుపుతాయి."}, {"id": 120, "subject": "Geography", "question": "The term watershed refers to:", "options": ["An area draining to a common outlet", "A type of cyclone", "A coastal current", "A desert dune"], "answer": 0, "explanation": "A watershed is the land area draining to a common point or outlet.", "te": "ఒకే నిష్క్రమణ బిందువుకు నీరు చేరే భూభాగం వాటర్‌షెడ్."}, {"id": 121, "subject": "Society", "question": "Sanskritisation is a concept associated with sociologist:", "options": ["M. N. Srinivas", "G. S. Ghurye", "A. R. Desai", "D. P. Mukerji"], "answer": 0, "explanation": "M. N. Srinivas used Sanskritisation to explain certain forms of social mobility.", "te": "సంస్కృతీకరణ భావనను ఎం.ఎన్. శ్రీనివాస్ వివరించాడు."}, {"id": 122, "subject": "Society", "question": "The concept of dominant caste is associated with:", "options": ["M. N. Srinivas", "B. R. Ambedkar", "Mahatma Gandhi", "Jyotiba Phule"], "answer": 0, "explanation": "M. N. Srinivas developed the concept of dominant caste.", "te": "ఆధిపత్య కులం భావనను ఎం.ఎన్. శ్రీనివాస్ అభివృద్ధి చేశాడు."}, {"id": 123, "subject": "Society", "question": "The Constitution's equality before law is guaranteed by:", "options": ["Article 14", "Article 19", "Article 25", "Article 51A"], "answer": 0, "explanation": "Article 14 guarantees equality before law and equal protection of laws.", "te": "ఆర్టికల్ 14 చట్టం ముందు సమానత్వాన్ని హామీ ఇస్తుంది."}, {"id": 124, "subject": "Society", "question": "The National Commission for Women was established as a statutory body under an Act of:", "options": ["1990", "1986", "2005", "2013"], "answer": 0, "explanation": "The National Commission for Women Act was enacted in 1990.", "te": "జాతీయ మహిళా కమిషన్ చట్టం 1990లో రూపొందింది."}, {"id": 125, "subject": "Society", "question": "The term social exclusion refers to:", "options": ["Processes that prevent groups from full participation", "Only migration between villages", "A type of family", "A tax exemption"], "answer": 0, "explanation": "Social exclusion restricts access to resources, rights and participation.", "te": "సామాజిక వనరులు, హక్కులు, భాగస్వామ్యానికి అడ్డంకులు సామాజిక బహిష్కరణ."}, {"id": 126, "subject": "Society", "question": "Which constitutional article prohibits discrimination on grounds listed in it?", "options": ["Article 15", "Article 20", "Article 29", "Article 368"], "answer": 0, "explanation": "Article 15 prohibits specified forms of discrimination by the State.", "te": "ఆర్టికల్ 15 నిర్దిష్ట ప్రాతిపదికలపై వివక్షను నిషేధిస్తుంది."}, {"id": 127, "subject": "Society", "question": "The term demographic dividend refers to potential economic benefit from:", "options": ["A relatively large working-age population", "A very high old-age dependency ratio", "Falling literacy", "Declining workforce participation only"], "answer": 0, "explanation": "A favourable age structure can support growth if jobs, skills and health are adequate.", "te": "పని వయస్సు జనాభా అధికంగా ఉండటం వల్ల సరైన ఉపాధి, నైపుణ్యాలు ఉంటే ఆర్థిక లాభం కలగవచ్చు."}, {"id": 128, "subject": "Society", "question": "A self-help group is commonly organised around:", "options": ["Collective savings and mutual support", "Only electoral campaigning", "Military training", "Judicial appointments"], "answer": 0, "explanation": "SHGs commonly mobilise members for savings, credit and collective action.", "te": "స్వయం సహాయక సంఘాలు పొదుపు, రుణం, పరస్పర సహకారం కోసం ఏర్పడతాయి."}, {"id": 129, "subject": "Society", "question": "The term gender division of labour refers to:", "options": ["Allocation of tasks by socially constructed gender roles", "Only division of land", "A factory shift pattern", "A constitutional schedule"], "answer": 0, "explanation": "Gender norms often shape paid and unpaid work allocation.", "te": "లింగ ఆధారిత సామాజిక పాత్రలు పనుల విభజనను ప్రభావితం చేస్తాయి."}, {"id": 130, "subject": "Society", "question": "The main aim of social justice is to:", "options": ["Reduce structural inequalities and ensure fair access", "Preserve unequal access", "Replace constitutional rights", "Restrict public services"], "answer": 0, "explanation": "Social justice seeks fairness, dignity and reduction of systemic disadvantage.", "te": "సామాజిక న్యాయం అసమానతలను తగ్గించి గౌరవం, సమాన అవకాశాలను పెంచుతుంది."}, {"id": 131, "subject": "Current Affairs", "question": "Which body publishes India's Consumer Price Index (CPI) inflation data?", "options": ["National Statistical Office", "Election Commission", "UPSC", "NITI Aayog alone"], "answer": 0, "explanation": "The NSO under MoSPI releases CPI data.", "te": "MoSPI పరిధిలోని NSO CPI గణాంకాలను విడుదల చేస్తుంది."}, {"id": 132, "subject": "Current Affairs", "question": "The Finance Commission is constituted under:", "options": ["Article 280", "Article 324", "Article 148", "Article 356"], "answer": 0, "explanation": "Article 280 provides for a Finance Commission.", "te": "ఆర్టికల్ 280 ఆర్థిక సంఘానికి సంబంధించినది."}, {"id": 133, "subject": "Current Affairs", "question": "The Comptroller and Auditor General of India is provided under:", "options": ["Article 148", "Article 280", "Article 110", "Article 21"], "answer": 0, "explanation": "Article 148 provides for the CAG of India.", "te": "ఆర్టికల్ 148 CAG పదవిని ఏర్పాటు చేస్తుంది."}, {"id": 134, "subject": "Current Affairs", "question": "The NITI Aayog was established in:", "options": ["2015", "2010", "2005", "2020"], "answer": 0, "explanation": "NITI Aayog was established on 1 January 2015.", "te": "నీతి ఆయోగ్ 1 జనవరి 2015న ఏర్పడింది."}, {"id": 135, "subject": "Current Affairs", "question": "The Paris Agreement is primarily related to:", "options": ["Climate change", "International postal services", "Nuclear disarmament", "Ocean shipping tariffs"], "answer": 0, "explanation": "The Paris Agreement is a global climate treaty adopted in 2015.", "te": "పారిస్ ఒప్పందం వాతావరణ మార్పులకు సంబంధించిన అంతర్జాతీయ ఒప్పందం."}, {"id": 136, "subject": "Current Affairs", "question": "The World Health Organization is a specialised agency of:", "options": ["United Nations", "World Bank", "WTO", "OECD"], "answer": 0, "explanation": "WHO is a UN specialised agency for international public health.", "te": "WHO ఐక్యరాజ్యసమితి ప్రత్యేక ఆరోగ్య సంస్థ."}, {"id": 137, "subject": "Current Affairs", "question": "The repo rate is the rate at which:", "options": ["RBI lends short-term funds to banks against eligible securities", "Banks lend to customers for home loans", "Government taxes imports", "SEBI lends to stock exchanges"], "answer": 0, "explanation": "The repo rate is a key RBI policy rate for lending to banks against securities.", "te": "రెపో రేటు అనేది RBI బ్యాంకులకు సెక్యూరిటీలపై రుణమిచ్చే విధాన రేటు."}, {"id": 138, "subject": "Current Affairs", "question": "The Election Commission of India is established under:", "options": ["Article 324", "Article 280", "Article 76", "Article 124"], "answer": 0, "explanation": "Article 324 vests superintendence, direction and control of elections in the ECI.", "te": "ఆర్టికల్ 324 ఎన్నికల నిర్వహణ అధికారాన్ని ఎన్నికల సంఘానికి ఇస్తుంది."}, {"id": 139, "subject": "Current Affairs", "question": "The International Court of Justice is located at:", "options": ["The Hague", "Geneva", "New York", "Paris"], "answer": 0, "explanation": "The ICJ is seated at the Peace Palace in The Hague.", "te": "అంతర్జాతీయ న్యాయస్థానం హేగ్ నగరంలో ఉంది."}, {"id": 140, "subject": "Current Affairs", "question": "A biodiversity hotspot is identified using high endemism and:", "options": ["Significant habitat loss", "High population alone", "High rainfall alone", "Large urban area"], "answer": 0, "explanation": "Hotspots combine high endemism with extensive habitat loss.", "te": "అధిక స్థానిక జాతులు, గణనీయమైన నివాస నష్టం బయోడైవర్సిటీ హాట్‌స్పాట్ లక్షణాలు."}, {"id": 141, "subject": "Mental Ability", "question": "If 7 : 49, then 9 : ?", "options": ["72", "81", "90", "99"], "answer": 1, "explanation": "The second number is the square of the first: 9² = 81.", "te": "రెండవ సంఖ్య మొదటి సంఖ్య వర్గం; 9² = 81."}, {"id": 142, "subject": "Mental Ability", "question": "Find the next number: 1, 4, 9, 16, 25, __", "options": ["30", "32", "36", "49"], "answer": 2, "explanation": "These are consecutive squares; next is 6² = 36.", "te": "ఇవి వరుస వర్గాలు; తదుపరి 6² = 36."}, {"id": 143, "subject": "Mental Ability", "question": "If SOUTH is written as TPVUI, then NORTH is written as:", "options": ["OPSUI", "OPSTI", "MPSUI", "OPRUI"], "answer": 0, "explanation": "Each letter is shifted one place forward.", "te": "ప్రతి అక్షరాన్ని ఒక స్థానం ముందుకు మార్చారు."}, {"id": 144, "subject": "Mental Ability", "question": "A is taller than B. B is taller than C. Who is shortest?", "options": ["A", "B", "C", "Cannot be determined"], "answer": 2, "explanation": "The order is A > B > C, so C is shortest.", "te": "A > B > C కాబట్టి C అత్యల్ప ఎత్తు."}, {"id": 145, "subject": "Mental Ability", "question": "A man faces west and turns 90° clockwise. Which direction does he face?", "options": ["North", "South", "East", "West"], "answer": 0, "explanation": "A 90-degree clockwise turn from west points north.", "te": "పడమర నుంచి 90° సవ్యదిశలో తిరిగితే ఉత్తరం."}, {"id": 146, "subject": "Mental Ability", "question": "If 3x = 27, x equals:", "options": ["6", "7", "8", "9"], "answer": 3, "explanation": "Divide both sides by 3: x = 9.", "te": "రెండు వైపులా 3తో భాగిస్తే x=9."}, {"id": 147, "subject": "Mental Ability", "question": "A number increased by 20% becomes 120. Original number is:", "options": ["90", "100", "110", "115"], "answer": 1, "explanation": "1.2x = 120, so x = 100.", "te": "1.2x=120 కాబట్టి అసలు సంఖ్య 100."}, {"id": 148, "subject": "Mental Ability", "question": "The median of 3, 7, 9, 11, 15 is:", "options": ["7", "9", "11", "15"], "answer": 1, "explanation": "The middle value in the ordered list is 9.", "te": "క్రమంలో మధ్య విలువ 9."}, {"id": 149, "subject": "Mental Ability", "question": "A sum doubles in 8 years at simple interest. The annual rate is:", "options": ["10%", "12.5%", "15%", "20%"], "answer": 1, "explanation": "Interest equals principal in 8 years; rate = 100/8 = 12.5%.", "te": "8 ఏళ్లలో వడ్డీ మూలధనంతో సమానం; రేటు 12.5%."}, {"id": 150, "subject": "Mental Ability", "question": "If 12 men complete a job in 15 days, 20 men at the same rate take:", "options": ["6 days", "9 days", "10 days", "12 days"], "answer": 1, "explanation": "Total work = 12×15 = 180 man-days; 180/20 = 9 days.", "te": "మొత్తం పని 180 మనిషి-రోజులు; 20 మందికి 9 రోజులు."}], "topics": [{"name": "Indian History", "description": "Ancient: Indus Valley Civilization; Vedic Age; Buddhism and Jainism; Mauryan and Gupta administration, society, economy, religion, art, architecture and literature; Harshavardhana. Medieval: Chola administration; Delhi Sultanate; Mughal administration, society, economy, religion, art, architecture, language and literature; Bhakti and Sufi movements; Shivaji and Marathas; arrival of Europeans. Modern: Revolt of 1857; British expansion and administration; social and religious reform; national movement and regional contributors; post-independence integration and reorganisation.", "te": "ప్రాచీన భారతదేశం: సింధు నాగరికత, వేద కాలం, బౌద్ధం–జైనం, మౌర్య–గుప్తుల పాలన, సమాజం, ఆర్థిక వ్యవస్థ, కళలు, సాహిత్యం, హర్షవర్ధనుడు. మధ్యయుగం: చోళుల స్థానిక పాలన, ఢిల్లీ సుల్తానులు, మొఘలులు, భక్తి–సూఫీ ఉద్యమాలు, శివాజీ, యూరోపియన్ల రాక. ఆధునికం: 1857 తిరుగుబాటు, బ్రిటిష్ విస్తరణ, సామాజిక సంస్కరణలు, జాతీయోద్యమం, స్వాతంత్ర్యానంతర సమీకరణ."}, {"name": "Geography", "description": "Physical geography: Earth and solar system; Earth's interior; landforms; atmosphere and climate; tides, waves and currents. India and Andhra Pradesh: physiography, climate, drainage, soils and vegetation; natural hazards and disaster management. Economic geography: resources, agriculture, agro-based activities, industries and industrial regions, transport, communication, tourism and trade. Human geography: human development, demographics, urbanisation, migration, racial, tribal, religious and linguistic groups.", "te": "భౌతిక భూగోళశాస్త్రం: భూమి–సౌరవ్యవస్థ, భూమి అంతర్భాగాలు, భూరూపాలు, వాతావరణం, సముద్ర అలలు–ఆటుపోట్లు–ప్రవాహాలు. భారతదేశం మరియు ఆంధ్రప్రదేశ్: భౌతిక విభాగాలు, వాతావరణం, నదులు, నేలలు, వృక్ష సంపద, ప్రకృతి వైపరీత్యాలు. ఆర్థిక భూగోళశాస్త్రం: వనరులు, వ్యవసాయం, పరిశ్రమలు, రవాణా, పర్యాటకం, వాణిజ్యం. మానవ భూగోళశాస్త్రం: జనాభా, పట్టణీకరణ, వలసలు, గిరిజన–భాషా సమూహాలు."}, {"name": "Indian Society", "description": "Structure: family, marriage, kinship, caste, tribe, ethnicity, religion and women. Social issues: casteism, communalism, regionalisation, crimes against women, child abuse, child labour, youth unrest and agitation. Welfare mechanisms: public policies and programmes; constitutional and statutory safeguards for SCs, STs, minorities, BCs, women, persons with disabilities and children.", "te": "సమాజ నిర్మాణం: కుటుంబం, వివాహం, బంధుత్వం, కులం, తెగలు, జాతి, మతం, మహిళల స్థితి. సామాజిక సమస్యలు: కులవివక్ష, మత ఘర్షణలు, ప్రాంతీయత, మహిళలపై నేరాలు, బాలల దుర్వినియోగం, బాల కార్మికత్వం, యువత అసంతృప్తి. సంక్షేమ వ్యవస్థలు: ప్రభుత్వ విధానాలు, పథకాలు; SC, ST, మైనారిటీలు, BCలు, మహిళలు, దివ్యాంగులు, పిల్లల రక్షణకు రాజ్యాంగ–చట్టపరమైన ఏర్పాట్లు."}, {"name": "Current Affairs", "description": "Track major international, national and Andhra Pradesh events. Prioritise official releases, government schemes, budgets, policy decisions, reports, indices, court judgments, science and technology, environment, awards, sports and important appointments. Maintain a dated fact sheet and verify names, dates, figures and issuing institutions from primary sources.", "te": "అంతర్జాతీయ, జాతీయ, ఆంధ్రప్రదేశ్‌కు సంబంధించిన ముఖ్య సంఘటనలను ప్రతిరోజూ చదవాలి. ప్రభుత్వ ప్రకటనలు, పథకాలు, బడ్జెట్లు, విధాన నిర్ణయాలు, నివేదికలు, సూచీలు, న్యాయస్థాన తీర్పులు, విజ్ఞానం–సాంకేతికత, పర్యావరణం, అవార్డులు, క్రీడలు, నియామకాలకు ప్రాధాన్యత ఇవ్వాలి. తేదీతో కూడిన నోట్స్ తయారు చేసి అధికారిక మూలాలతో ధృవీకరించాలి."}, {"name": "Mental Ability", "description": "Logical reasoning: deductive, inductive and abductive reasoning; statements and assumptions, arguments, conclusions and courses of action. Mental ability: number and letter series, odd one out, coding-decoding, relations, shapes and subdivisions. Numeracy: number system, order of magnitude, averages, ratio and proportion, percentages, simple and compound interest, time and work, time and distance. Data analysis: tables, bar diagrams, line graphs and pie charts.", "te": "తార్కిక ఆలోచన: నిగమన, ఆగమన, వివరణాత్మక తర్కం; వాక్యాలు–ఊహలు, వాదనలు, నిర్ధారణలు, చర్యల ఎంపిక. మానసిక సామర్థ్యం: సంఖ్యా–అక్షర శ్రేణులు, భిన్నమైనది గుర్తించడం, కోడింగ్–డీకోడింగ్, సంబంధాలు, ఆకృతులు. గణితం: సంఖ్యా వ్యవస్థ, సగటు, నిష్పత్తి, శాతాలు, సరళ–చక్రవడ్డీ, పని–కాలం, వేగం–దూరం. డేటా విశ్లేషణ: పట్టికలు, బార్ చార్టులు, రేఖాచిత్రాలు, పై చార్టులు."}], "notes": [{"title": "Indus Valley Civilization / సింధు నాగరికత", "en": "Urban Bronze Age civilisation known for planned streets, drainage, baked-brick structures, weights and measures, craft production and long-distance trade. Major sites include Harappa, Mohenjo-daro, Dholavira, Lothal and Kalibangan. The script remains undeciphered; avoid presenting any single-cause decline theory as settled.", "te": "నగర ప్రణాళిక, మురుగునీటి కాలువలు, కాల్చిన ఇటుకల నిర్మాణాలు, కొలతలు, చేతివృత్తులు, వాణిజ్యం ముఖ్య లక్షణాలు. హరప్పా, మొహెంజోదారో, ధోలవీరా, లోథల్, కాలిబంగన్ ముఖ్య కేంద్రాలు. లిపి ఇంకా పూర్తిగా చదవబడలేదు; నాగరికత పతనానికి ఒకే కారణం అని ఖచ్చితంగా చెప్పరాదు."}, {"title": "Buddhism and Jainism / బౌద్ధం మరియు జైనం", "en": "Both emerged in the 6th century BCE milieu and questioned ritual dominance. Buddhism is associated with Gautama Buddha and the Four Noble Truths and Eightfold Path. Jainism is associated with the Tirthankaras, especially Mahavira; its core ethical ideas include ahimsa, aparigraha and anekantavada.", "te": "రెండు మతాలు క్రీస్తుపూర్వం 6వ శతాబ్దపు సామాజిక–మత వాతావరణంలో బలపడ్డాయి. బౌద్ధంలో నాలుగు ఆర్య సత్యాలు, అష్టాంగ మార్గం ముఖ్యమైనవి. జైనంలో మహావీరుడు, అహింస, అపరిగ్రహం, అనేకాంతవాదం ముఖ్య భావనలు."}, {"title": "Mauryan and Gupta periods / మౌర్య–గుప్త యుగాలు", "en": "The Mauryan state is associated with centralised administration, Ashoka's inscriptions and dhamma policy. The Gupta period is noted for developments in Sanskrit literature, mathematics, art and temple architecture. Treat 'Golden Age' as a conventional label, not a claim that all regions and social groups experienced equal prosperity.", "te": "మౌర్య పాలన కేంద్రీకృత పరిపాలన, అశోకుని శాసనాలు, ధమ్మ విధానంతో ప్రసిద్ధి. గుప్త యుగంలో సంస్కృత సాహిత్యం, గణితం, కళలు, దేవాలయ నిర్మాణం అభివృద్ధి చెందాయి. 'స్వర్ణయుగం' అనేది సంప్రదాయంగా వాడే పదం మాత్రమే; అందరికీ సమాన అభివృద్ధి జరిగిందని అర్థం కాదు."}, {"title": "1857 Revolt / 1857 తిరుగుబాటు", "en": "The uprising involved soldiers, rulers, peasants and local groups, with varied causes including military grievances, annexation policies, revenue pressures and religious-cultural anxieties. After suppression, the Crown assumed direct rule in 1858 and the East India Company's governing role ended.", "te": "ఈ తిరుగుబాటులో సైనికులు, పాలకులు, రైతులు, స్థానిక సమూహాలు పాల్గొన్నారు. సైనిక అసంతృప్తి, రాజ్యాల విలీన విధానం, పన్నుల భారం, మత–సాంస్కృతిక ఆందోళనలు కారణాలు. 1858లో కంపెనీ పాలన ముగిసి బ్రిటిష్ కిరీటం ప్రత్యక్ష పాలన చేపట్టింది."}, {"title": "Indian National Movement / భారత జాతీయోద్యమం", "en": "Study the movement chronologically: early associations and the Indian National Congress (1885); Swadeshi and revolutionary currents; Home Rule; Gandhian mass movements; constitutional negotiations; Quit India; independence and partition. Link national developments with regional leaders and movements.", "te": "జాతీయోద్యమాన్ని కాలక్రమంలో చదవాలి: ప్రారంభ సంఘాలు, 1885లో కాంగ్రెస్ స్థాపన, స్వదేశీ ఉద్యమం, విప్లవ ధోరణులు, హోం రూల్, గాంధేయ ప్రజా ఉద్యమాలు, రాజ్యాంగ చర్చలు, క్విట్ ఇండియా, స్వాతంత్ర్యం–విభజన. జాతీయ పరిణామాలను ప్రాంతీయ నాయకులు, ఉద్యమాలతో అనుసంధానించాలి."}, {"title": "Indian physiography / భారత భౌతిక స్వరూపం", "en": "Major divisions include the Himalayas, Northern Plains, Peninsular Plateau, Indian Desert, Coastal Plains and Islands. Relief influences climate, drainage, agriculture, settlement and transport. Compare the Western and Eastern Ghats, Himalayan and Peninsular rivers, and east- and west-flowing river systems.", "te": "భారతదేశ ప్రధాన భౌతిక విభాగాలు హిమాలయాలు, ఉత్తర మైదానాలు, ద్వీపకల్ప పీఠభూమి, భారత ఎడారి, తీర మైదానాలు, దీవులు. భూరూపాలు వాతావరణం, నదులు, వ్యవసాయం, నివాసాలు, రవాణాపై ప్రభావం చూపుతాయి."}, {"title": "Andhra Pradesh geography / ఆంధ్రప్రదేశ్ భూగోళశాస్త్రం", "en": "Prepare location, coastal plain, Eastern Ghats, river basins, delta regions, rainfall pattern, cyclones, soils, crops, irrigation, minerals, ports, industrial corridors and district-level demographic features. Use current official state publications for changing district and project facts.", "te": "రాష్ట్ర స్థానం, తీర మైదానం, తూర్పు కనుమలు, నదీ పరివాహక ప్రాంతాలు, డెల్టాలు, వర్షపాతం, తుఫానులు, నేలలు, పంటలు, సాగునీరు, ఖనిజాలు, ఓడరేవులు, పారిశ్రామిక కారిడార్లు, జిల్లాల జనాభా లక్షణాలు చదవాలి. మారే గణాంకాలకు తాజా ప్రభుత్వ నివేదికలు ఉపయోగించాలి."}, {"title": "Society and welfare / సమాజం–సంక్షేమం", "en": "Distinguish caste (a historically embedded social hierarchy) from class (often linked to economic position); understand kinship, patriarchy, social mobility, pluralism and regional identity. For welfare mechanisms, learn the constitutional article or statute, implementing institution, target group and grievance route for each safeguard.", "te": "కులం, వర్గం మధ్య తేడా; బంధుత్వం, పితృస్వామ్యం, సామాజిక చలనం, బహుళత్వం, ప్రాంతీయ గుర్తింపును అర్థం చేసుకోవాలి. సంక్షేమ ఏర్పాట్లలో సంబంధిత రాజ్యాంగ అధికరణం/చట్టం, అమలు సంస్థ, లబ్ధిదారుల వర్గం, ఫిర్యాదు పరిష్కార మార్గం గుర్తుంచుకోవాలి."}, {"title": "Current affairs method / కరెంట్ అఫైర్స్ పద్ధతి", "en": "Use a daily 30–45 minute cycle: read one reliable newspaper; check PIB, AP government and department releases; note what happened, why it matters, the institution involved and one exam-relevant fact; revise weekly. Avoid unverified social-media claims.", "te": "రోజుకు 30–45 నిమిషాలు కేటాయించండి: నమ్మదగిన పత్రిక చదవండి; PIB, AP ప్రభుత్వ శాఖల ప్రకటనలు చూడండి; ఏమి జరిగింది, ఎందుకు ముఖ్యం, ఏ సంస్థకు సంబంధించింది, పరీక్షకు ఉపయోగపడే అంశం రాయండి; వారానికి ఒకసారి పునశ్చరణ చేయండి."}, {"title": "Reasoning and numeracy / తర్కం–గణితం", "en": "For each question, identify the rule before calculating. Useful formulas: Average = sum / count; Percentage = (part / whole) × 100; SI = PRT / 100; Speed = distance / time; Work rate adds for independent workers. In data interpretation, read units and totals before comparing values.", "te": "ప్రతి ప్రశ్నలో లెక్కకు ముందు నియమాన్ని గుర్తించండి. సగటు = మొత్తం / సంఖ్య; శాతం = (భాగం / మొత్తం) × 100; సరళ వడ్డీ = P×R×T/100; వేగం = దూరం / కాలం. డేటా విశ్లేషణలో పోలికకు ముందు యూనిట్లు, మొత్తం విలువలు చూడాలి."}]};
